<script setup>
import {ref} from 'vue';import {Head,useForm} from '@inertiajs/vue3';import Footer from '../Components/Footer.vue';import Errors from '../Components/Errors.vue';import {art,crew} from '../art';
const show=ref(false),form=useForm({username:'',password:''});function submit(){form.post('/login',{onFinish:()=>form.reset('password')})}
</script><template><Head title="Sign in"/><div class="login">
<main class="login-layout"><section class="identity"><div><img class="banner" :src="art.banner" alt="SUSHI Clerks Comprehensive Exam Reviewer"><div class="caption"><p class="eyebrow">Your next round starts here</p><h1>Good things come<br>one roll at a time.</h1><p>Practice your clinical knowledge, revisit tricky questions, and keep your progress together.</p><div class="crew"><div v-for="(c,s) in crew" :key="s"><img :src="c.image" :alt="c.name"><strong>{{s}}</strong></div></div></div></div></section>
<section class="access"><div class="login-form"><img class="seal" :src="art.logo" alt="SUSHI"><p class="eyebrow">Your seat at the counter</p><h2>Welcome back.</h2><p class="muted">Sign in to pick up where you left off.</p><Errors :errors="form.errors"/><form @submit.prevent="submit"><label>Username<input v-model="form.username" name="username" autocomplete="username" autocapitalize="none" spellcheck="false" required></label><label>Password<span class="password-input"><input v-model="form.password" name="password" aria-label="Password" :type="show?'text':'password'" autocomplete="current-password" required><button type="button" class="plain" @click="show=!show" :aria-label="show?'Hide password':'Show password'" :aria-pressed="show">{{show?'Hide':'Show'}}</button></span></label><button class="primary full" :disabled="form.processing">{{form.processing?'Signing in…':"Let's roll →"}}</button></form><p class="help">Need help signing in? Contact your administrator.</p><hr><p class="help">Fresh questions. Familiar faces. Progress that stays with you.</p></div></section></main><Footer/></div></template>
